import { readFile, writeFile, rename, mkdir } from "node:fs/promises";
import { randomBytes } from "node:crypto";
import { dirname } from "node:path";

export function newId() {
  return randomBytes(6).toString("base64url");
}

export function createStore(filePath) {
  async function load() {
    try {
      const data = JSON.parse(await readFile(filePath, "utf8"));
      return Array.isArray(data) ? data : [];
    } catch (err) {
      if (err.code === "ENOENT") return [];
      throw err;
    }
  }

  async function save(books) {
    await mkdir(dirname(filePath), { recursive: true });
    const tmp = `${filePath}.${process.pid}.${Date.now()}.tmp`;
    await writeFile(tmp, JSON.stringify(books, null, 2));
    await rename(tmp, filePath);
  }

  return {
    async list() {
      return load();
    },

    async get(id) {
      return (await load()).find((b) => b.id === id) ?? null;
    },

    async add({ title, author, notes = "" }) {
      const book = {
        id: newId(),
        title: String(title).trim(),
        author: String(author).trim(),
        notes: String(notes).trim(),
        status: "reading",
        addedAt: new Date().toISOString(),
        finishedAt: null,
      };
      if (!book.title || !book.author) {
        throw Object.assign(new Error("title and author are required"), { status: 400 });
      }
      const books = await load();
      books.push(book);
      await save(books);
      return book;
    },

    async finish(id) {
      const books = await load();
      const book = books.find((b) => b.id === id);
      if (!book) return null;
      if (book.status !== "finished") {
        book.status = "finished";
        book.finishedAt = new Date().toISOString();
        await save(books);
      }
      return book;
    },
  };
}

