export function esc(s) {
  return String(s)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

const css = `
  body { font-family: system-ui, sans-serif; max-width: 640px; margin: 2rem auto; padding: 0 1rem; color: #222; }
  h1 a { color: inherit; text-decoration: none; }
  h2 { margin-bottom: .5rem; color: #555; font-size: 1rem; text-transform: uppercase; letter-spacing: .05em; }
  ul { list-style: none; padding: 0; }
  li { padding: .6rem 0; border-bottom: 1px solid #eee; display: flex; justify-content: space-between; align-items: baseline; gap: 1rem; }
  li a { color: #0645ad; text-decoration: none; }
  li a:hover { text-decoration: underline; }
  .author { color: #777; }
  form.inline { display: inline; }
  button { font: inherit; padding: .15rem .6rem; cursor: pointer; }
  .add label { display: block; margin: .5rem 0; }
  .add input, .add textarea { width: 100%; box-sizing: border-box; padding: .4rem; font: inherit; }
  .meta { color: #777; font-size: .9rem; }
  .notes { white-space: pre-wrap; background: #fafafa; border: 1px solid #eee; padding: .75rem; border-radius: 4px; }
  .error { color: #b00; }
  .empty { color: #999; font-style: italic; }
`;

export function layout(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${esc(title)}</title>
<style>${css}</style>
</head>
<body>
<h1><a href="/">My Books</a></h1>
${body}
</body>
</html>`;
}

function bookList(books) {
  if (!books.length) return `<p class="empty">None yet.</p>`;
  const items = books
    .map(
      (b) => `<li>
  <span><a href="/books/${esc(b.id)}">${esc(b.title)}</a> <span class="author">— ${esc(b.author)}</span></span>
  ${
    b.status === "reading"
      ? `<form class="inline" method="post" action="/books/${esc(b.id)}/finish"><button>Finished</button></form>`
      : ""
  }
</li>`,
    )
    .join("\n");
  return `<ul>${items}</ul>`;
}

export function homePage({ reading, finished, error = "" }) {
  return layout(
    "My Books",
    `
<section>
  <h2>Currently reading</h2>
  ${bookList(reading)}
  <h2>Finished</h2>
  ${bookList(finished)}
</section>
<section class="add">
  <h2>Add a book</h2>
  ${error ? `<p class="error">${esc(error)}</p>` : ""}
  <form method="post" action="/books">
    <label>Title <input name="title" required></label>
    <label>Author <input name="author" required></label>
    <label>Notes <textarea name="notes" rows="3"></textarea></label>
    <button type="submit">Add book</button>
  </form>
</section>`,
  );
}

export function bookPage(book, baseUrl) {
  const link = `${baseUrl}/books/${book.id}`;
  return layout(
    book.title,
    `
<article>
  <h2 style="font-size:1.4rem;text-transform:none;letter-spacing:0;color:#222">${esc(book.title)}</h2>
  <p class="author">by ${esc(book.author)}</p>
  <p class="meta">
    ${book.status === "finished" ? `Finished ${esc(book.finishedAt?.slice(0, 10) ?? "")}` : "Currently reading"}
  </p>
  ${book.status === "reading" ? `<form class="inline" method="post" action="/books/${esc(book.id)}/finish"><button>Mark as finished</button></form>` : ""}
  <h3>Notes</h3>
  <p class="notes">${book.notes ? esc(book.notes) : `<span class="empty">No notes yet.</span>`}</p>
  <h3>Share</h3>
  <p><input readonly size="40" value="${esc(link)}" onclick="this.select()"></p>
  <p><a href="/">&larr; All books</a></p>
</article>`,
  );
}

export function notFoundPage(message = "Not found") {
  return layout(message, `<p class="error">${esc(message)}</p><p><a href="/">Back to all books</a></p>`);
}

