import { describe, it, expect, beforeEach, afterEach } from "vitest";
import { mkdtemp, rm, readFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { createStore } from "./store.js";

describe("store", () => {
  let dir, file, store;

  beforeEach(async () => {
    dir = await mkdtemp(join(tmpdir(), "books-"));
    file = join(dir, "books.json");
    store = createStore(file);
  });

  afterEach(async () => {
    await rm(dir, { recursive: true, force: true });
  });

  it("starts empty when file does not exist", async () => {
    expect(await store.list()).toEqual([]);
    expect(await store.get("nope")).toBeNull();
  });

  it("adds a book and persists it to the JSON file", async () => {
    const book = await store.add({ title: "Dune", author: "Frank Herbert", notes: "desert stuff" });
    expect(book).toMatchObject({ title: "Dune", author: "Frank Herbert", status: "reading" });

    const again = createStore(file);
    expect(await again.get(book.id)).toMatchObject({ title: "Dune", notes: "desert stuff" });
    expect(JSON.parse(await readFile(file, "utf8"))).toHaveLength(1);
  });

  it("trims whitespace", async () => {
    const book = await store.add({ title: "  Dune  ", author: "  Frank Herbert ", notes: "  " });
    expect(book).toMatchObject({ title: "Dune", author: "Frank Herbert", notes: "" });
  });

  it("rejects missing title or author", async () => {
    await expect(store.add({ title: "  ", author: "X" })).rejects.toThrow(/required/);
    await expect(store.add({ title: "X", author: "" })).rejects.toThrow(/required/);
    expect(await store.list()).toEqual([]);
  });

  it("marks a book finished", async () => {
    const book = await store.add({ title: "Dune", author: "Frank Herbert" });
    const done = await store.finish(book.id);
    expect(done).toMatchObject({ status: "finished" });
    expect(done.finishedAt).toBeTruthy();

    const again = createStore(file);
    expect(await again.get(book.id)).toMatchObject({ status: "finished" });
  });

  it("finish is idempotent and returns null for unknown ids", async () => {
    const book = await store.add({ title: "Dune", author: "Frank Herbert" });
    const first = await store.finish(book.id);
    const second = await store.finish(book.id);
    expect(second.finishedAt).toBe(first.finishedAt);
    expect(await store.finish("nope")).toBeNull();
  });

  it("handles corrupt file gracefully only for missing files", async () => {
    await readFile(file).catch(() => {});
    store = createStore(join(dir, "sub", "deep", "books.json"));
    expect(await store.list()).toEqual([]);
    await store.add({ title: "A", author: "B" });
  });
});

