import { describe, it, expect, beforeAll, afterAll, beforeEach } from "vitest";
import { createServer } from "node:http";
import { mkdtemp, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { handler } from "./server.js";
import { createStore } from "./store.js";

let server, base, dir, file;

beforeAll(async () => {
  dir = await mkdtemp(join(tmpdir(), "books-http-"));
  file = join(dir, "books.json");
  process.env.DATA_FILE = file;
  server = createServer((req, res) =>
    handler(req, res).catch((err) => {
      res.writeHead(err.status || 500);
      res.end("boom");
    }),
  );
  await new Promise((r) => server.listen(0, r));
  base = `http://127.0.0.1:${server.address().port}`;
});

afterAll(async () => {
  server.close();
  await rm(dir, { recursive: true, force: true });
});

beforeEach(async () => {
  await rm(file, { force: true });
});

async function follow(res) {
  if (res.status === 303) return follow(await fetch(base + res.headers.get("location")));
  return res;
}

describe("web app", () => {
  it("shows an empty home page", async () => {
    const res = await fetch(`${base}/`);
    const html = await res.text();
    expect(res.status).toBe(200);
    expect(html).toContain("Currently reading");
    expect(html).toContain("None yet");
  });

  it("adds a book via form and shows its detail page", async () => {
    const res = await follow(
      await fetch(`${base}/books`, {
        method: "POST",
        headers: { "Content-Type": "application/x-www-form-urlencoded" },
        body: new URLSearchParams({ title: "Dune", author: "Frank Herbert", notes: "spice must flow" }),
      }),
    );
    expect(res.status).toBe(200);
    const html = await res.text();
    expect(html).toContain("Dune");
    expect(html).toContain("Frank Herbert");
    expect(html).toContain("spice must flow");
    expect(res.url).toMatch(/\/books\/[\w-]+$/);

    const home = await (await fetch(`${base}/`)).text();
    expect(home).toContain("Dune");
  });

  it("escapes HTML in user input", async () => {
    await fetch(`${base}/books`, {
      method: "POST",
      headers: { "Content-Type": "application/x-www-form-urlencoded" },
      body: new URLSearchParams({ title: "<script>evil()</script>", author: "A&B" }),
    });
    const home = await (await fetch(`${base}/`)).text();
    expect(home).toContain("&lt;script&gt;");
    expect(home).toContain("A&amp;B");
    expect(home).not.toContain("<script>evil");
  });

  it("rejects a book without title", async () => {
    const res = await fetch(`${base}/books`, {
      method: "POST",
      headers: { "Content-Type": "application/x-www-form-urlencoded" },
      body: new URLSearchParams({ title: "  ", author: "X" }),
    });
    expect(res.status).toBe(400);
    expect(await (await fetch(`${base}/`)).text()).toContain("None yet");
  });

  it("marks a book finished from its page", async () => {
    const created = await follow(
      await fetch(`${base}/books`, {
        method: "POST",
        headers: { "Content-Type": "application/x-www-form-urlencoded" },
        body: new URLSearchParams({ title: "Dune", author: "Frank Herbert" }),
      }),
    );
    const id = created.url.split("/").pop();

    await fetch(`${base}/books/${id}/finish`, { method: "POST", redirect: "manual" });
    const page = await (await fetch(`${base}/books/${id}`)).text();
    expect(page).toContain("Finished");

    const home = await (await fetch(`${base}/`)).text();
    const finishedSection = home.slice(home.indexOf("Finished</h2>"));
    expect(finishedSection).toContain("Dune");
  });

  it("returns 404 for unknown books", async () => {
    const res = await fetch(`${base}/books/doesnotexist`);
    expect(res.status).toBe(404);
  });
});

