import { createServer } from "node:http";
import { extname, join } from "node:path";
import { createStore } from "./store.js";
import { homePage, bookPage, notFoundPage } from "./views.js";

const PORT = process.env.PORT || 3000;
const DATA_FILE = process.env.DATA_FILE || join(process.cwd(), "books.json");
const store = createStore(DATA_FILE);

function readBody(req) {
  return new Promise((resolve, reject) => {
    let body = "";
    req.on("data", (c) => {
      body += c;
      if (body.length > 1e6) {
        reject(Object.assign(new Error("Payload too large"), { status: 413 }));
        req.destroy();
      }
    });
    req.on("end", () => resolve(body));
    req.on("error", reject);
  });
}

function send(res, status, html, headers = {}) {
  res.writeHead(status, { "Content-Type": "text/html; charset=utf-8", ...headers });
  res.end(html);
}

function redirect(res, location) {
  res.writeHead(303, { Location: location });
  res.end();
}

function baseUrl(req) {
  const host = req.headers.host || `localhost:${PORT}`;
  return `http://${host}`;
}

async function handler(req, res) {
  const url = new URL(req.url, baseUrl(req));
  const path = url.pathname.replace(/\/+$/, "") || "/";

  if (req.method === "GET" && path === "/") {
    const books = await store.list();
    send(res, 200, homePage({ reading: books.filter((b) => b.status === "reading"), finished: books.filter((b) => b.status === "finished") }));
  } else if (req.method === "GET" && /^\/books\/[\w-]+$/.test(path)) {
    const book = await store.get(decodeURIComponent(path.slice(7)));
    if (!book) return send(res, 404, notFoundPage("No book with that id."));
    send(res, 200, bookPage(book, baseUrl(req)));
  } else if (req.method === "POST" && path === "/books") {
    const fields = Object.fromEntries(new URLSearchParams(await readBody(req)));
    try {
      const book = await store.add({ title: fields.title, author: fields.author, notes: fields.notes });
      redirect(res, `/books/${book.id}`);
    } catch (err) {
      if (err.status === 400) {
        return send(res, 400, homePage({ reading: [], finished: [], error: "Title and author are required." }));
      }
      throw err;
    }
  } else if (req.method === "POST" && /^\/books\/[\w-]+\/finish$/.test(path)) {
    const id = decodeURIComponent(path.slice(7, -8));
    const book = await store.finish(id);
    if (!book) return send(res, 404, notFoundPage("No book with that id."));
    redirect(res, `/books/${book.id}`);
  } else {
    send(res, 404, notFoundPage());
  }
}

